Review this durable order flow against the accepted at-least-once contract. Completion must survive process loss, consumers must be idempotent, and redrive may replay any message.

```go
func Complete(ctx context.Context, id string) error {
    if err := orders.MarkComplete(ctx, id); err != nil { return err }
    return broker.Publish(ctx, OrderCompleted{ID: id})
}
func Consume(ctx context.Context, msg Message) error {
    msg.Ack()
    return projections.Apply(ctx, msg.OrderID)
}
